        if (y < aminy) aminy = y; else if (y > amaxy) amaxy = y;
    }
    double bminx = CGAL::to_double(B[0].x()), bmaxx = bminx;
    double bminy = CGAL::to_double(B[0].y()), bmaxy = bminy;
    for (size_t i = 1; i < B.size(); ++i) {
        const double x = CGAL::to_double(B[i].x());
        const double y = CGAL::to_double(B[i].y());
        if (x < bminx) bminx = x; else if (x > bmaxx) bmaxx = x;
        if (y < bminy) bminy = y; else if (y > bmaxy) bmaxy = y;
    }
    return amaxx < bminx || bmaxx < aminx || amaxy < bminy || bmaxy < aminy;
}

inline bool intersect(const std::vector<Point>& P_in,
                      const std::vector<Point>& Q_in,
                      std::vector<Point>& result,
                      bool q_pre_deduped = false) {
    // Thread-local scratch for the deduplicated inputs; reused across calls so
    // the steady state performs no heap allocation here.
    thread_local std::vector<Point> P_verts, Q_verts;
    dedup_into(P_in, P_verts);
    const std::vector<Point>* Q_ptr = &Q_in;
    if (!q_pre_deduped) {
        dedup_into(Q_in, Q_verts);
        Q_ptr = &Q_verts;
    }

    // Cheap reject before the O(n*m) clip.  Axis-aligned boxes of convex
    // polygons are tight enough to catch many prune-miss disjoint pairs.
    if (aabb_disjoint_points(P_verts, *Q_ptr)) {
        result.clear();
        return false;
    }

    // clip returns a reference to its own thread-local buffer, distinct from
    // `result`, so deduping straight into `result` is safe.
    dedup_into(sh_double::clip(P_verts, *Q_ptr), result);
    if (result.size() < 3) {
        result.clear();
        return false;
    }
    return true;
}

